-- Meeting room booking calendar for Strategy Calendar.
-- Data is imported from Strategy_Calendarv2/Reservations.csv and kept separate from strategy_events.

create table if not exists public.meeting_room_reservations (
  id uuid primary key default gen_random_uuid(),
  legacy_id text unique,
  reservation_date date not null,
  room text not null,
  start_time time not null,
  end_time time not null,
  booker_name text not null,
  work_group text not null,
  topic text not null,
  created_by uuid default auth.uid() references public.profiles(user_id) on delete set null,
  cancelled_at timestamptz,
  cancelled_by uuid references public.profiles(user_id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint meeting_room_reservations_room_check check (room in ('ห้องประชุม 1', 'ห้องประชุม 2', 'ห้องสมุด')),
  constraint meeting_room_reservations_time_order check (end_time > start_time),
  constraint meeting_room_reservations_booker_not_blank check (length(trim(booker_name)) > 0),
  constraint meeting_room_reservations_work_group_not_blank check (length(trim(work_group)) > 0),
  constraint meeting_room_reservations_topic_not_blank check (length(trim(topic)) > 0)
);

create index if not exists idx_meeting_room_reservations_date on public.meeting_room_reservations(reservation_date);
create index if not exists idx_meeting_room_reservations_room_date on public.meeting_room_reservations(room, reservation_date);
create index if not exists idx_meeting_room_reservations_work_group on public.meeting_room_reservations(work_group);
create index if not exists idx_meeting_room_reservations_created_by on public.meeting_room_reservations(created_by);
create index if not exists idx_meeting_room_reservations_cancelled_by on public.meeting_room_reservations(cancelled_by);

drop trigger if exists set_meeting_room_reservations_updated_at on public.meeting_room_reservations;
create trigger set_meeting_room_reservations_updated_at
before update on public.meeting_room_reservations
for each row
execute function public.set_updated_at();

alter table public.meeting_room_reservations enable row level security;

drop policy if exists "meeting room reservations active users read" on public.meeting_room_reservations;
create policy "meeting room reservations active users read"
on public.meeting_room_reservations
for select
to authenticated
using (public.current_user_role() is not null);

drop policy if exists "meeting room reservations active users insert" on public.meeting_room_reservations;
create policy "meeting room reservations active users insert"
on public.meeting_room_reservations
for insert
to authenticated
with check (
  public.current_user_role() is not null
  and created_by = auth.uid()
);

drop policy if exists "meeting room reservations update own or admin" on public.meeting_room_reservations;
create policy "meeting room reservations update own or admin"
on public.meeting_room_reservations
for update
to authenticated
using (
  created_by = auth.uid()
  or public.is_privileged_role(array['super_admin', 'admin']::public.user_role[])
)
with check (
  created_by = auth.uid()
  or public.is_privileged_role(array['super_admin', 'admin']::public.user_role[])
);

drop policy if exists "meeting room reservations delete admin" on public.meeting_room_reservations;
create policy "meeting room reservations delete admin"
on public.meeting_room_reservations
for delete
to authenticated
using (public.is_privileged_role(array['super_admin', 'admin']::public.user_role[]));

grant select, insert, update, delete on public.meeting_room_reservations to authenticated;

